const items = $input.all();
return items.map(item => {
  const text = item.json.text || item.json.message?.text || '';
  const user = item.json.user || item.json.message?.user || 'Unknown';
  const userName = item.json.user_name || item.json.userName || user;
  const timestamp = item.json.ts || '';

  // Parse standup format: "Done: ... | Doing: ... | Blockers: ..."
  // Also supports "Yesterday: ... | Today: ... | Blockers: ..."
  const sections = text.split(/\||\n/).map(s => s.trim());

  let done = '';
  let doing = '';
  let blockers = '';

  sections.forEach(section => {
    const lower = section.toLowerCase();
    if (lower.startsWith('done:') || lower.startsWith('yesterday:') || lower.startsWith('completed:')) {
      done = section.replace(/^(done|yesterday|completed):/i, '').trim();
    } else if (lower.startsWith('doing:') || lower.startsWith('today:') || lower.startsWith('working on:')) {
      doing = section.replace(/^(doing|today|working on):/i, '').trim();
    } else if (lower.startsWith('blocker') || lower.startsWith('blocked:') || lower.startsWith('issues:')) {
      blockers = section.replace(/^(blockers?|blocked|issues):/i, '').trim();
    }
  });

  // If no structured format, use full text
  if (!done && !doing && !blockers) {
    doing = text;
  }

  return {
    json: {
      userName,
      userId: user,
      done,
      doing,
      blockers,
      date: new Date().toISOString().split('T')[0],
      fullText: text,
      hasBlockers: blockers.length > 0 && blockers.toLowerCase() !== 'none'
    }
  };
});

