const items = $input.all();
const byMember = {};

items.forEach(item => {
  const props = item.json.properties || {};
  const member = props['Team Member']?.rich_text?.map(t => t.plain_text).join('') || 'Unknown';
  const date = props['Date']?.date?.start || '';
  const hasBlockers = props['Has Blockers']?.checkbox || false;

  if (!byMember[member]) byMember[member] = { entries: 0, blockerDays: 0 };
  byMember[member].entries++;
  if (hasBlockers) byMember[member].blockerDays++;
});

const summary = Object.entries(byMember).map(([member, data]) =>
  `• ${member}: ${data.entries} standup(s), ${data.blockerDays} day(s) with blockers`
).join('\n');

const totalEntries = items.length;
const totalBlockerDays = Object.values(byMember).reduce((sum, d) => sum + d.blockerDays, 0);

return [{
  json: {
    weekOf: $now.minus({ days: 5 }).format('yyyy-MM-dd'),
    totalEntries,
    teamMembers: Object.keys(byMember).length,
    totalBlockerDays,
    summary
  }
}];

